mapper.update:
update t_exam_answer
set ean_is_correct = #{isCorrect}, ean_score = #{score}, ean_updated_at = now()
where ean_id = #{eanId}

update t_exam_answer
set ean_score = #{score}, ean_updated_at = now()
where ean_id = #{eanId}

update t_tal
set tal_status = #{status}, tal_exam_record_id = #{recordId}, tal_updated_at = now()
where tal_id = #{talId}

mapper.select:
select r.erc_id as recordId, ifnull(u.real_name, u.nick_name) as candidateName, pos.pos_title as positionTitle, p.epa_name as paperName, s.esd_pass_threshold as passThreshold, p.epa_total_score as paperTotalScore, date_format(r.erc_submit_at, '%Y-%m-%d %H:%i') as submitAt, r.erc_status as status, r.erc_pass_status as passStatus, r.erc_total_score as totalScore, res.ers_objective_score as objectiveScore, res.ers_subjective_score as subjectiveScore, res.ers_comment as comment from t_exam_record r join t_exam_schedule s on s.esd_id = r.erc_schedule_id join t_exam_paper p on p.epa_id = s.esd_paper_id join t_pos pos on pos.pos_id = s.esd_position_id join t_tal t on t.tal_id = r.erc_candidate_id left join sys_user u on u.user_id = t.tal_user_id left join t_exam_result res on res.ers_record_id = r.erc_id where pos.pos_company_id = #{companyId} and r.erc_status in (2, 4)
and s.esd_position_id = #{positionId}
and r.erc_pass_status = #{passStatus}
order by r.erc_submit_at desc, r.erc_id desc
